class _Q:
    def __init__(self):
        self.inbox = []
        self.outbox = []
        self.moves = 0
    def _fill(self):
        if not self.outbox:
            while self.inbox:
                self.outbox.append(self.inbox.pop())
                self.moves += 1
    def deq(self):
        self._fill()
        return self.outbox.pop() if self.outbox else None
    def front(self):
        self._fill()
        return self.outbox[-1] if self.outbox else None

